// LEARN(ts.everyday-types.null): with strictNullChecks, absence is part of the type and must be handled.

interface User {
  login: string;
  nickname: string | null; // always present, may be null (a nullable column)
  phone?: string; // may be missing altogether
}

const users: User[] = [
  { login: "ayse", nickname: "Ayşe" },
  { login: "mehmet", nickname: null, phone: "+90 555 000 0000" },
];

// find() can miss, so its type is User | undefined.
const ali = users.find((u) => u.login === "ali");
// console.log(ali.login);
// error TS18048: 'ali' is possibly 'undefined'.
if (ali === undefined) {
  console.log("no user ali");
} else {
  console.log(ali.login); // narrowed to User in this branch
}

// Map.get is the same: V | undefined.
const byLogin = new Map(users.map((u) => [u.login, u]));
const mehmet = byLogin.get("mehmet");
if (mehmet !== undefined) {
  // console.log(mehmet.nickname.length);
  // error TS18047: 'mehmet.nickname' is possibly 'null'.
  console.log(`${mehmet.login}: ${mehmet.nickname ?? "(no nickname)"}`);
}

// The non-null assertion ! silences the check and moves the crash to run time.
try {
  console.log(byLogin.get("ali")!.login);
} catch (e) {
  console.log(e instanceof TypeError ? "TypeError: the ! was wrong" : e);
}

files.examples/02_optional_chaining.ts:
// LEARN(ts.everyday-types.null): ?. stops at null/undefined; ?? defaults only for null/undefined, unlike ||.

interface Settings {
  pageSize?: number;
  title?: string;
  owner?: { name: string; email?: string } | null;
}

const settings: Settings = { pageSize: 0, title: "", owner: null };

// || replaces every falsy value (0, "", false, NaN); ?? only null and undefined.
const { pageSize, title } = settings;
console.log(`pageSize: ${pageSize || 50} vs ${pageSize ?? 50}`);
console.log(`title: "${title || "Untitled"}" vs "${title ?? "Untitled"}"`);

// ?. short-circuits the rest of the chain when owner is null or undefined.
// const email = settings.owner.email;
// error TS18049: 'settings.owner' is possibly 'null' or 'undefined'.
console.log(settings.owner?.email?.toLowerCase() ?? "no email");

const team: Settings = { owner: { name: "Işıl" } };
console.log(team.owner?.name.toLocaleUpperCase("tr") ?? "no owner");

// Optional call: invoke the callback only if one was passed.
function save(onDone?: (id: string) => void): void {
  onDone?.("a1");
}
save();
save((id) => console.log(`saved ${id}`));

// ??= assigns only when the current value is null or undefined.
const cache: { token?: string } = {};
cache.token ??= "t-1";
cache.token ??= "t-2";
console.log(cache.token);

